"""DCSS observations from numbered, enlarged contact sheets, never filenames.

The frozen review index binds every position to SHA-256. Repeated animation
frames can share a visual caption, but each file gets its own verified record.
Removal recommendations are suggestions only; this script never deletes PNGs.
"""
import hashlib
import json
import re
from pathlib import Path
from art_retention_metadata import load_retention_decisions, apply_retention_decision

ROOT = Path(__file__).resolve().parents[1]
LIBRARY = ROOT / 'src/ArtLibrary'
OBSERVATIONS = {}
REMOVAL = {}
OVERSIZE_SOURCE = 'https://github.com/crawl/crawl/blob/0.16.2/crawl-ref/source/rltiles/dc-mon.txt'
DEMON_SOURCE = 'https://github.com/crawl/crawl/blob/0.16.2/crawl-ref/source/rltiles/dc-demon.txt'


def sheet(number, entries, prefix=''):
    for entry in entries.split('|'):
        positions, caption = entry.strip().split(':', 1)
        bounds = positions.strip().split('-')
        start, end = int(bounds[0]), int(bounds[-1])
        for position in range(start, end + 1):
            key = (number, position)
            if key in OBSERVATIONS:
                raise ValueError(f'Duplicate observation: {key}')
            OBSERVATIONS[key] = prefix + caption.strip() + '.'


def rows(number, captions, prefix=''):
    sheet(number, '|'.join(f'{i}:{caption.strip()}' for i, caption in enumerate(captions.split('|'), 1)), prefix)


def suggest(number, positions, reason):
    for position in positions:
        REMOVAL[(number, position)] = reason


