def main():
    index = json.loads((LIBRARY / 'dcss-review-index.json').read_text(encoding='utf-8'))
    result, missing = {}, []
    decisions=load_retention_decisions(ROOT)
    indexed_ids = {a['id'] for s in index for a in s['assets']}
    for batch in index:
        for position, asset in enumerate(batch['assets'], 1):
            key = (int(batch['sheet']), position)
            path = ROOT / asset['path']
            if not path.exists():
                continue  # Respect ongoing user deletion; never restore files.
            if hashlib.sha256(path.read_bytes()).hexdigest() != asset['sha256']:
                raise ValueError(f'Reviewed PNG changed: {path}')
            if key not in OBSERVATIONS:
                missing.append(asset['id']); continue
            record = dict(descriptionEn=OBSERVATIONS[key], sha256=asset['sha256'],
                semanticStatus='visually_described', reviewMethod='individual_numbered_contact_sheet_96px',
                reviewSheet=batch['sheet'], reviewPosition=position)
            if key in REMOVAL:
                record['retentionReview'] = dict(recommendation='review_removal', reason=REMOVAL[key], userApproved=False)
            asset_id = asset['id']
            if asset_id.startswith('dcss/player/') and not asset_id.startswith(('dcss/player/felids/', 'dcss/player/transform/')):
                mode = 'base_32' if asset_id.startswith('dcss/player/base/') else 'overlay_32'
                record['composition'] = dict(mode=mode, canvas=[32,32], evidence='src/NaviDnD/Helpers/HeroDoll.cs:Render')
            is_pair = re.search(r'_(top|bottom)(?:_(new|old))?$', asset_id) is not None
            demon_part = asset_id.startswith('dcss/monster/panlord/') and is_pair
            unique_part = asset_id.startswith('dcss/monster/unique/') and is_pair
            if demon_part or unique_part:
                record['composition'] = dict(mode='oversized_part', fitsSingleTile=False,
                    documentedFamilyCanvas=[32,48], evidence=DEMON_SOURCE if demon_part else OVERSIZE_SOURCE,
                    note='Reviewed top/bottom export of a taller source composition; no resizing or recomposition performed.')
                record['retentionReview'] = dict(recommendation='review_removal', userApproved=False,
                    reason='Верхняя/нижняя часть высокого составного спрайта. Для этого семейства в исходниках DCSS документирован холст 32×48; сборка выходит за пределы 32×32. Предлагается исключить по вашему правилу; файл не удалён.')
            result[asset['id']] = apply_retention_decision(asset['id'],record,decisions)
    missing.extend(p.relative_to(ROOT/'src/icons').with_suffix('').as_posix()
                   for p in (ROOT/'src/icons/dcss').rglob('*.png')
                   if p.relative_to(ROOT/'src/icons').with_suffix('').as_posix() not in indexed_ids)
    target = LIBRARY / 'dcss-annotations.json'
    temporary = target.with_suffix('.json.new')
    temporary.write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding='utf-8')
    temporary.replace(target)
    report = dict(described=len(result), remaining=len(missing), removalSuggestions=sum(a.get('retentionReview',{}).get('recommendation')=='review_removal' for a in result.values()),
                  retainedByUser=sum(a.get('retentionReview',{}).get('recommendation')=='keep' for a in result.values()),
                  oversizedParts=sum(a.get('composition',{}).get('mode')=='oversized_part' for a in result.values()),
                  missing=missing, noFilesDeleted=True)
    (LIBRARY / 'dcss-description-coverage.json').write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding='utf-8')
    print(f"DCSS described: {len(result)}; remaining: {len(missing)}; removal suggestions: {report['removalSuggestions']}")


if __name__ == '__main__':
    main()
